update public.learning_paths
set
  title = 'Marketing Analytics',
  goal = 'Marketing Analytics',
  summary = 'Frame marketing analytics problems as decision questions with clear stakeholders, actions, metrics, and constraints, then prepare marketing data and apply segmentation, customer lifetime value, predictive models, experiments, attribution, pricing analytics, and responsible targeting.',
  data = $mkanjson${"slug": "marketing-analytics", "title": "Marketing Analytics", "description": "Frame marketing analytics problems as decision questions with clear stakeholders, actions, metrics, and constraints, then prepare marketing data and apply segmentation, customer lifetime value, predictive models, experiments, attribution, pricing analytics, and responsible targeting.", "topics": [{"id": "9eeff532-6580-46fa-b50b-b5da6ec01a28", "type": "topic", "title": "Marketing Analytics as Decision Science", "description": "Students begin by learning that analytics is not report-making; it is disciplined decision support. The unit links business questions, customer strategy, measurement design, and managerial action.", "children": [{"id": "a8d20804-8e6d-44d0-9633-63bac9d42150", "type": "subtopic", "title": "Business questions before methods", "children": [{"id": "6c991122-972e-4163-a2fb-f1dcc06a5469", "type": "concept", "title": "Decision owner, business question, action threshold, and time horizon"}, {"id": "e351bb14-4f03-4e20-b1bd-868ffd5f73e3", "type": "concept", "title": "Descriptive, diagnostic, predictive, prescriptive, and causal questions"}, {"id": "5a4f0a1d-b98c-455e-b803-b86b938a5689", "type": "concept", "title": "Translating vague goals into testable analytic problems"}], "description": "Students learn to start with a decision, not a dataset. Good marketing analytics clarifies what action will change if the analysis is right."}, {"id": "4b8f9785-a4b1-42be-b0f8-ae6278a2336b", "type": "subtopic", "title": "Marketing strategy and analytics fit", "children": [{"id": "0ec64b51-da7f-44c2-9513-b032b5994b69", "type": "concept", "title": "STP, marketing mix, funnel, and customer equity logic"}, {"id": "94e31196-aae7-470f-a00c-960124fbba09", "type": "concept", "title": "Acquisition, conversion, retention, monetization, loyalty, and advocacy"}, {"id": "dde8d92a-1831-4e2b-ae5c-e7e50d218f03", "type": "concept", "title": "How analytics connects to budgeting, ROI, and resource allocation"}], "description": "Analytics becomes useful when it supports segmentation, targeting, positioning, product, price, promotion, channel, and retention decisions."}, {"id": "cfac81a7-aa0f-4ce7-8f49-b6eca57fa326", "type": "subtopic", "title": "Analytic workflow and reproducibility", "children": [{"id": "1a1a40eb-82e7-40b2-9e0d-20d5f9db045c", "type": "concept", "title": "Scoping, data audit, cleaning, exploration, modeling, validation, and reporting"}, {"id": "29a57ac5-e743-4267-99f2-9cc05c7e9aad", "type": "concept", "title": "Assumptions, versioning, reproducible files, and documentation"}, {"id": "924eefc6-8409-4696-b1f2-1cf5b9cc1300", "type": "concept", "title": "Decision-ready recommendations and post-decision learning loops"}], "description": "Students learn the workflow from problem framing through data, model, interpretation, recommendation, and monitoring."}]}, {"id": "8511ed97-41b8-4bcc-aace-2a90e4446344", "type": "topic", "title": "Marketing Data Sources, Martech, SQL, and Data Quality", "description": "This section teaches students where marketing data comes from, how it is joined, and why data quality determines whether analysis can be trusted.", "children": [{"id": "35d2124a-7c75-4a73-b93f-256bf58cd19b", "type": "subtopic", "title": "Data ecosystem and martech", "children": [{"id": "8b25d8e0-b01e-4295-8283-23dd39bd197c", "type": "concept", "title": "CRM, CDP, web analytics, ad platforms, email, ecommerce, surveys, POS, and loyalty data"}, {"id": "1859a231-fa2a-4b96-b58a-452d510718c5", "type": "concept", "title": "First-party, second-party, third-party, syndicated, and public data"}, {"id": "d21cdb23-3a8a-47eb-a0a2-da2b8d69ec78", "type": "concept", "title": "Identity resolution, event tracking, tags, UTMs, pixels, and APIs"}], "description": "Marketing data comes from many tools that rarely agree perfectly. Students learn the ecosystem before analyzing it."}, {"id": "0052b48f-cf55-43e8-a0ee-dd03c8ceac40", "type": "subtopic", "title": "SQL and data preparation", "children": [{"id": "ea0b8197-506d-46a1-9983-1dc994eaf81d", "type": "concept", "title": "SELECT, WHERE, JOIN, GROUP BY, CASE, window functions, and date logic"}, {"id": "bde4b119-cc5b-465a-8e52-447dd3a3456d", "type": "concept", "title": "Customer, transaction, event, campaign, product, and touchpoint tables"}, {"id": "77bbc757-06ae-4a88-8566-5204cb91ade7", "type": "concept", "title": "Feature engineering for recency, frequency, monetary value, source, and engagement"}], "description": "Students practice the extraction and joining skills needed to turn raw records into analyzable marketing tables."}, {"id": "de31c3fa-9003-4669-9df3-c2f132b96273", "type": "subtopic", "title": "Data quality and governance", "children": [{"id": "03fe35a4-592e-4fdc-8ba3-f2c9913f0138", "type": "concept", "title": "Data dictionaries, metric definitions, lineage, and ownership"}, {"id": "a6bb8dd8-49b8-444e-a52e-993f3d357ff0", "type": "concept", "title": "Missing data, outliers, bot traffic, duplicate customers, and attribution gaps"}, {"id": "9721f823-5bf5-44a3-8eb3-efc154ff2a10", "type": "concept", "title": "Quality checks, reconciliation, access control, and audit trails"}], "description": "Students learn why missingness, duplication, tracking drift, and inconsistent definitions can destroy analytic credibility."}]}, {"id": "be35d93c-cdbb-4d35-9a65-78c8fb241710", "type": "topic", "title": "Metrics, KPIs, Dashboards, and Insight Communication", "description": "Students learn to design metrics that match strategy, avoid vanity measures, and communicate insights in dashboards that drive decisions.", "children": [{"id": "5c999598-65ca-472c-aed0-572b9bbcf349", "type": "subtopic", "title": "Metric architecture", "children": [{"id": "559d15d0-102a-4169-82a3-4a0b40eab7c5", "type": "concept", "title": "North-star metric, input metrics, output metrics, guardrails, and leading indicators"}, {"id": "46b9b98a-0fe9-4a65-9620-7f39bc48ec7a", "type": "concept", "title": "Awareness, reach, engagement, conversion, retention, revenue, profit, and loyalty metrics"}, {"id": "5561fdf1-a082-4ca0-9fd9-902bc5c0c411", "type": "concept", "title": "Metric trees that connect marketing activity to business outcomes"}], "description": "Students learn to distinguish strategic KPIs from diagnostic metrics and vanity measures."}, {"id": "fdaff5c6-dcbd-4c00-ae56-526de8430e4f", "type": "subtopic", "title": "Dashboard design", "children": [{"id": "8349cd44-ae8f-4d32-8b73-764a82a43763", "type": "concept", "title": "Executive, manager, channel, campaign, and analyst dashboard roles"}, {"id": "e4d110fa-c938-473b-a951-fb8e972141ac", "type": "concept", "title": "Visualization choices, filters, annotations, benchmarks, and targets"}, {"id": "a51169c7-07b0-488e-892c-b3cd5a1ea5c2", "type": "concept", "title": "Avoiding clutter, misleading scales, and disconnected chart collections"}], "description": "A dashboard should answer recurring questions quickly. Students design dashboards around users, decisions, and exceptions."}, {"id": "2c40f8c3-84ad-48b1-a250-3c7f1dcb4cae", "type": "subtopic", "title": "Insight storytelling", "children": [{"id": "3e1c55b1-2708-43c2-bd73-59d117567210", "type": "concept", "title": "Situation, complication, insight, implication, and action"}, {"id": "6a01eda3-7747-4037-9d9a-d69e41b8d03b", "type": "concept", "title": "Executive summaries, decision memos, and meeting narratives"}, {"id": "5108935f-03fb-4f42-90b0-78aa71d8f38d", "type": "concept", "title": "Uncertainty, caveats, confidence, and next-best analysis"}], "description": "Students learn to communicate analysis as a recommendation, not a pile of charts."}]}, {"id": "ffaafc4b-10d7-46e3-9f5c-c09aff3e0407", "type": "topic", "title": "Consumer Behavior, Customer Journeys, and CRM Analytics", "description": "This topic connects behavioral theory with observed customer data so students can interpret journeys, funnels, engagement, and relationship signals.", "children": [{"id": "d8b34e69-529f-4ad5-b547-061db8c50fcd", "type": "subtopic", "title": "Behavioral foundations", "children": [{"id": "db6ac7d8-6cf2-401a-a21e-0dabe711a889", "type": "concept", "title": "Decision process, involvement, heuristics, and behavioral bias"}, {"id": "5eb9c263-45eb-45d3-8a17-b51b7a56b2f5", "type": "concept", "title": "Cultural, social, demographic, and psychographic drivers"}, {"id": "b0005274-b32e-480a-9c3c-428d3a45e6b4", "type": "concept", "title": "Post-purchase behavior, satisfaction, loyalty, and advocacy"}], "description": "Students connect observable behavior to attention, motivation, perception, memory, attitudes, persuasion, and social influence."}, {"id": "d664cdd1-88ad-4b3e-b173-320c18f829d0", "type": "subtopic", "title": "Journey and funnel analytics", "children": [{"id": "6cea6fd4-5236-4ad1-b0b3-a91504d57401", "type": "concept", "title": "Funnels, paths, drop-off, time lag, micro-conversions, and cohorts"}, {"id": "36b6a4c3-36bc-425a-93a0-4ffc1bf52703", "type": "concept", "title": "Journey stages, pain points, content needs, and touchpoint roles"}, {"id": "03f3fbc8-3163-44cb-81fc-bda8c10723de", "type": "concept", "title": "Omnichannel journeys and cross-device measurement limits"}], "description": "Students analyze how customers move through awareness, consideration, conversion, onboarding, use, repeat purchase, and advocacy."}, {"id": "b3cc5932-d248-4a4a-9de7-b8a226330ac3", "type": "subtopic", "title": "CRM and relationship data", "children": [{"id": "1307543d-36c6-4416-8ba6-280b31a4eb3a", "type": "concept", "title": "Lead scoring, account history, service interactions, offers, and lifecycle stages"}, {"id": "ec54eadc-8d55-4526-b5b4-4b3f74292410", "type": "concept", "title": "RFM, engagement scoring, next-best action, and customer health"}, {"id": "21b9b80c-7b59-4eca-a94b-137d8d308004", "type": "concept", "title": "Sales and marketing alignment through shared customer data"}], "description": "CRM analytics turns customer histories into decisions about service, sales, retention, and personalization."}]}, {"id": "8fd251c7-e052-49bb-8caa-93049d7a258b", "type": "topic", "title": "Segmentation, Targeting, Clustering, and Personalization", "description": "Students study how to group customers meaningfully and turn segments into targeting, personalization, and positioning decisions.", "children": [{"id": "f8ca82e0-bdc2-4482-b63d-9aac93997bbb", "type": "subtopic", "title": "Segmentation logic", "children": [{"id": "11ea1989-fa8d-4843-8ab2-90c4ddc54bfb", "type": "concept", "title": "Needs-based, behavioral, demographic, attitudinal, value-based, and occasion-based segments"}, {"id": "c34dec67-1363-4118-9657-6591838a20b6", "type": "concept", "title": "Segment size, growth, profitability, reachability, stability, and distinctiveness"}, {"id": "ecd46029-5c00-4a08-bc2c-1472defd9f30", "type": "concept", "title": "Targeting choices, positioning implications, and offer design"}], "description": "Segmentation is useful only when it changes decisions. Students learn to judge segments by actionability and value."}, {"id": "f531fa05-139a-4ba2-8847-7b4cdd84d953", "type": "subtopic", "title": "Clustering and profiling", "children": [{"id": "6d6269da-889f-4549-80ea-5af0bee4c2ec", "type": "concept", "title": "K-means, hierarchical clustering, mixture intuition, and distance metrics"}, {"id": "d3b7cdff-6e8b-4c65-be2a-1c9e72502773", "type": "concept", "title": "Feature scaling, number of clusters, validation, and cluster stability"}, {"id": "dd75fe28-c037-494b-9f1f-8b03903f0b62", "type": "concept", "title": "Personas, segment profiles, naming, and managerial translation"}], "description": "Students learn how clustering algorithms create groups and why interpretation matters as much as computation."}, {"id": "3e2d6de0-7a73-41a6-95b9-1021a6759aaf", "type": "subtopic", "title": "Personalization and recommendation", "children": [{"id": "889c0c5d-60d6-44e0-b47e-fcc42f65105b", "type": "concept", "title": "Rules-based personalization, propensity scores, recommendations, and dynamic content"}, {"id": "31d5ed77-f1f7-436a-a215-0227a38c88b5", "type": "concept", "title": "Cold start, overfitting, frequency, fatigue, and customer creepiness"}, {"id": "28d5c950-609c-4107-865b-349defe5c6ba", "type": "concept", "title": "Testing personalized treatments against generic alternatives"}], "description": "Students evaluate personalization as a tradeoff among relevance, efficiency, privacy, fairness, and customer experience."}]}, {"id": "72614548-47ca-42e7-a1b4-720e7068c0b1", "type": "topic", "title": "Customer Lifetime Value, Retention, Churn, and Customer Equity", "description": "This unit develops the financial logic of customer relationships: acquisition cost, retention, churn, margin, discounting, and long-run value.", "children": [{"id": "f467c77b-88be-4e99-9a00-7495e401187c", "type": "subtopic", "title": "CLV foundations", "children": [{"id": "ef821ca3-c58b-4ef4-9216-a2685037a04f", "type": "concept", "title": "Margin, retention, discount rate, purchase frequency, acquisition cost, and payback"}, {"id": "998c17ff-498f-46b8-bd32-abbccc5cadc0", "type": "concept", "title": "Historic, predictive, cohort, and probabilistic CLV"}, {"id": "42e31533-16a4-4e6c-9314-04b001c98976", "type": "concept", "title": "Customer equity, portfolio value, and segment profitability"}], "description": "Students learn CLV as the financial bridge between marketing actions and firm value."}, {"id": "97b4e675-8347-4b29-80ae-e344b04db846", "type": "subtopic", "title": "Churn and retention analytics", "children": [{"id": "4229b545-982f-440c-9425-a2d0b31f1ac5", "type": "concept", "title": "Voluntary churn, involuntary churn, inactivity, downgrades, and dormancy"}, {"id": "b92c2ba1-ca1a-4770-a7ce-50a4d262ca97", "type": "concept", "title": "Churn labels, observation windows, leakage, and class imbalance"}, {"id": "8107126e-75a4-4a02-834c-9d5a1cd278c7", "type": "concept", "title": "Retention offers, win-back, loyalty programs, and intervention timing"}], "description": "Retention is often more valuable than acquisition. Students learn to predict and diagnose churn while respecting causal limits."}, {"id": "a5786631-ee33-441a-ac9c-23ec53c6d965", "type": "subtopic", "title": "Customer acquisition economics", "children": [{"id": "3a4fa6ad-eb4b-4307-936f-ce18a0c9de16", "type": "concept", "title": "CAC, LTV:CAC, payback period, contribution margin, and unit economics"}, {"id": "d5a1fb7f-acef-4930-8efe-4b4810f3e480", "type": "concept", "title": "Acquisition source quality, cohort retention, and channel profitability"}, {"id": "f5fb0b7c-231d-49e0-8220-883ff16a7833", "type": "concept", "title": "Growth tradeoffs between scale, efficiency, and customer quality"}], "description": "Students connect CLV to CAC, media spend, channels, and growth quality."}]}, {"id": "ba1b02c7-c5b0-4004-9d45-f335a6cfac8f", "type": "topic", "title": "Marketing Research, Surveys, Sampling, and Measurement Validity", "description": "Students learn how survey and research design shape the quality of analytic conclusions before any model is built.", "children": [{"id": "a8d5f12f-a0df-4c68-bd23-cdfb9a10a93e", "type": "subtopic", "title": "Research design", "children": [{"id": "c615622e-14b4-4e5b-a6eb-9f47949bb195", "type": "concept", "title": "Problem definition, hypotheses, research objectives, and decision criteria"}, {"id": "4ff0baa3-98ab-4b1c-b2ae-e1e83e3257f0", "type": "concept", "title": "Exploratory, descriptive, causal, qualitative, quantitative, and mixed-method designs"}, {"id": "6e414db5-a511-45fe-8bcd-372c02a35870", "type": "concept", "title": "Primary data, secondary data, syndicated data, and behavioral data"}], "description": "Students learn to choose qualitative, quantitative, experimental, or mixed methods based on the decision problem."}, {"id": "0ece43c8-419f-4098-8394-0f18533bd08b", "type": "subtopic", "title": "Survey and sampling quality", "children": [{"id": "53577488-6ced-4a45-ba0e-b0c6f84cdef1", "type": "concept", "title": "Sampling frame, probability, nonprobability, bias, weighting, and response rate"}, {"id": "4d34dd8e-2eb6-46e7-bff9-9f037e5d97fd", "type": "concept", "title": "Question wording, order effects, scales, attention checks, and pretesting"}, {"id": "d0e4aa72-a24c-4c90-98d5-1610b2cc5322", "type": "concept", "title": "Reliability, construct validity, measurement error, and nonresponse"}], "description": "Bad survey design creates bad analytics. Students learn core validity threats and practical fixes."}, {"id": "d11d2d4a-e3ef-401e-b049-8b4b56efff81", "type": "subtopic", "title": "Ethics and insight reporting", "children": [{"id": "1afc9a08-6d28-411a-9e9b-b975229a9d41", "type": "concept", "title": "Consent, privacy, deception, incentives, and vulnerable populations"}, {"id": "44483178-ec54-456a-abe9-20e7cd26ece9", "type": "concept", "title": "Transparency about uncertainty, assumptions, and representativeness"}, {"id": "0c91c9a4-571f-4cf7-a110-2d29c0e5add0", "type": "concept", "title": "Turning research findings into actionable insight without overclaiming"}], "description": "Marketing research must respect respondents and communicate limitations clearly."}]}, {"id": "a728d1a2-13fa-43b2-a8a5-648a5eeaaa7e", "type": "topic", "title": "Predictive Modeling: Regression, Classification, and Forecasting", "description": "This section gives students applied modeling tools for predicting response, sales, churn, demand, and campaign outcomes.", "children": [{"id": "10c01c9a-6312-4006-9a6d-689522e3268a", "type": "subtopic", "title": "Regression and response modeling", "children": [{"id": "a63987db-926b-40f3-869c-52ea8c48f260", "type": "concept", "title": "Linear and logistic regression, interactions, nonlinearities, and transformations"}, {"id": "68d64287-8597-4497-9889-5d87163d93ba", "type": "concept", "title": "Response, conversion, sales, spend, price, and demand models"}, {"id": "9052a507-0601-46fb-aec1-dc8ac80f6cd3", "type": "concept", "title": "Coefficients, confidence, fit, residuals, and business interpretation"}], "description": "Students learn regression as a practical tool for explaining and predicting marketing outcomes."}, {"id": "f97e0d1a-b89a-4db8-be29-7e4153292252", "type": "subtopic", "title": "Classification and model evaluation", "children": [{"id": "20148cc0-e119-4dfc-86f9-290b813189d1", "type": "concept", "title": "Propensity modeling, churn prediction, lead scoring, and next-best offer"}, {"id": "1d8269b8-e947-4da4-bb9a-2cd5b98755ac", "type": "concept", "title": "Train/test splits, cross-validation, ROC/AUC, precision, recall, lift, and calibration"}, {"id": "416cb4ec-a661-4a45-b1a2-4f0c24694ad7", "type": "concept", "title": "Threshold selection, profit curves, and intervention economics"}], "description": "Predictive marketing models require careful evaluation against business costs and benefits."}, {"id": "9a922ad0-8e75-4f9b-ae9c-ba35ef5c1943", "type": "subtopic", "title": "Forecasting and uncertainty", "children": [{"id": "5c4784a3-2df8-4e1e-89f4-4d305dd7d674", "type": "concept", "title": "Trend, seasonality, moving averages, exponential smoothing, and regression forecasting"}, {"id": "1d9ef6a4-a2cf-416a-bdb3-850f66cf50c7", "type": "concept", "title": "Holdout validation, forecast error, scenario ranges, and confidence intervals"}, {"id": "8d12f8b1-d126-4287-a660-d50ee05d7ef2", "type": "concept", "title": "Promotions, holidays, launches, stockouts, and structural breaks"}], "description": "Students learn to forecast demand, traffic, leads, sales, and campaign performance while communicating uncertainty."}]}, {"id": "fe1d5913-9fc8-4d34-b863-cf71d1995958", "type": "topic", "title": "Experiments, A/B Testing, Lift, and Causal Inference", "description": "Students learn how to estimate what marketing caused, not just what happened near marketing activity.", "children": [{"id": "c45ecec6-c8e3-4a84-a7c4-0d315f792c5c", "type": "subtopic", "title": "Experiment design", "children": [{"id": "ac90e05d-e43a-4ce9-853d-80eeec7e9140", "type": "concept", "title": "Treatment, control, randomization, sample size, power, and preregistered metrics"}, {"id": "4935f1d2-beef-49c4-b679-49eedd6ffd9f", "type": "concept", "title": "A/B, multivariate, holdout, geo, matched-market, and field experiments"}, {"id": "0afb8808-a07d-4812-ab01-a9261efc2047", "type": "concept", "title": "Guardrail metrics, novelty effects, test duration, and interference"}], "description": "Students learn to design tests that answer a decision question with credible causal evidence."}, {"id": "e2e64f03-2c86-4232-b8e4-50941e868e1e", "type": "subtopic", "title": "Lift and incrementality", "children": [{"id": "dc763243-6e24-416c-b8d1-cdc7b81d3ce2", "type": "concept", "title": "Incremental revenue, conversion lift, brand lift, and sales lift"}, {"id": "60c148a4-9e0f-4ea8-abc1-9deaf5f534c4", "type": "concept", "title": "Selection bias, targeting bias, seasonality, and regression to the mean"}, {"id": "72b3429b-71dc-4fea-9e4d-c2dbca2557b6", "type": "concept", "title": "Platform lift studies, ghost ads, conversion lift, and holdout groups"}], "description": "Lift tells students what marketing added beyond what would have happened anyway."}, {"id": "e3fd2aaa-7c29-42ee-82b4-31bc19933f18", "type": "subtopic", "title": "Causal inference beyond experiments", "children": [{"id": "b2255398-86ce-4247-bd47-05efd708b5b6", "type": "concept", "title": "Difference-in-differences, matching, regression discontinuity, and synthetic control intuition"}, {"id": "8161b1a6-38ff-4f9e-b006-1b7814ff6234", "type": "concept", "title": "Confounding, omitted variables, parallel trends, and robustness checks"}, {"id": "3ec3326f-77ca-4ec1-9f3c-2d99680335bd", "type": "concept", "title": "Causal claims, limitations, and responsible recommendation language"}], "description": "When experiments are not feasible, students learn the assumptions behind quasi-experimental tools."}]}, {"id": "4c10fdb7-e21b-4d59-84db-361214711c5d", "type": "topic", "title": "Digital Analytics: Web, App, Search, Social, Email, and Content", "description": "This topic teaches the measurement logic of modern digital channels, from search intent to content engagement and conversion paths.", "children": [{"id": "de97e491-176a-482d-a57f-e2afeb1db5f2", "type": "subtopic", "title": "Web and app analytics", "children": [{"id": "f05022e3-86bf-4f1c-afc4-3c6432348e19", "type": "concept", "title": "Events, sessions, users, conversions, engagement, bounce, retention, and cohorts"}, {"id": "a96493c1-04ee-4a50-81c4-37b0a6b9858e", "type": "concept", "title": "GA4 event model, tag manager, UTM parameters, and goal configuration"}, {"id": "e67ef068-1b43-4414-8c9c-0716a98187ca", "type": "concept", "title": "Cross-device identity, consent mode, blockers, and measurement loss"}], "description": "Students learn how digital behavior is captured and how implementation choices shape reported performance."}, {"id": "73f7155c-5614-46f8-a6f4-f5261ce17d5c", "type": "subtopic", "title": "Search, social, and content analytics", "children": [{"id": "77c72cb7-0472-41af-b74e-ba4f0c4cf653", "type": "concept", "title": "SEO, SEM, search intent, quality score, rank, keywords, and landing pages"}, {"id": "481d04db-1ba2-4699-a662-171cb1cfe7c0", "type": "concept", "title": "Reach, impressions, engagement, shares, saves, comments, sentiment, and community growth"}, {"id": "782750dd-2c42-47dd-87a3-cb87075aeb50", "type": "concept", "title": "Content performance, editorial calendars, creator partnerships, and social listening"}], "description": "Digital channels have different intent, algorithms, and metrics. Students learn to interpret each channel on its own terms."}, {"id": "24a77625-4676-41fc-989c-f183e12566a5", "type": "subtopic", "title": "Email and lifecycle analytics", "children": [{"id": "cdb87cbb-5f64-4615-bd1f-c4d0252b6db2", "type": "concept", "title": "Deliverability, opens, clicks, conversions, unsubscribes, spam, and list health"}, {"id": "8cea10f9-76d3-46d7-8d9c-03cab21ba4fc", "type": "concept", "title": "Triggers, drip campaigns, nurture flows, abandoned carts, and reactivation"}, {"id": "92555c65-f602-4eae-9c8d-d427b035a189", "type": "concept", "title": "Frequency, fatigue, personalization, segmentation, and lifecycle lift"}], "description": "Students connect email and automation to customer lifecycle strategy."}]}, {"id": "b70f1a6a-3cf1-45fe-a3bf-34b2a561b89e", "type": "topic", "title": "Attribution, Incrementality, and Marketing Mix Modeling", "description": "Students compare attribution models, incrementality testing, and MMM so they can choose the right method for budget and performance questions.", "children": [{"id": "b5c26cfc-7126-42df-862a-b230468e578f", "type": "subtopic", "title": "Attribution models", "children": [{"id": "e2e76bb0-b3c3-40e6-902c-036b6838096c", "type": "concept", "title": "Last-click, first-click, linear, time-decay, position-based, algorithmic, and data-driven attribution"}, {"id": "85fc724e-a525-444a-9e2f-8cdfdd84b97d", "type": "concept", "title": "Touchpoints, lookback windows, cross-device gaps, view-through conversions, and dark social"}, {"id": "97bc34a1-4bb8-444d-9703-e244fe1ff0b9", "type": "concept", "title": "Attribution bias and the difference between credit assignment and causality"}], "description": "Students compare attribution approaches and learn why no attribution model is neutral."}, {"id": "9cd84118-765c-4f3f-9b8c-fa67b974d94c", "type": "subtopic", "title": "Marketing mix modeling", "children": [{"id": "bad28269-36bd-4d47-862d-bc0974e608f3", "type": "concept", "title": "Adstock, saturation, base sales, seasonality, price, promotions, distribution, and macro factors"}, {"id": "3114cfcb-9eee-4ba7-aa3e-da9594978686", "type": "concept", "title": "Model specification, calibration, validation, and budget scenarios"}, {"id": "63c2f44b-bcb4-45a9-b498-e9700ceee5d8", "type": "concept", "title": "MMM strengths when user-level tracking is limited"}], "description": "MMM estimates the relationship between spend, channels, external factors, and business outcomes at aggregate scale."}, {"id": "20e5153d-c4d0-44de-9302-59018e2cf7ab", "type": "subtopic", "title": "Budget optimization and decision use", "children": [{"id": "17a703d8-d63c-4791-a421-3cc929dea54d", "type": "concept", "title": "Channel allocation, marginal ROI, diminishing returns, and response curves"}, {"id": "eb7ffb02-6a08-4a81-9416-0f5cbc11569d", "type": "concept", "title": "Reconciling MMM, platform reports, lift studies, and attribution dashboards"}, {"id": "7c83350a-4720-49c4-9bbf-f5d9ffd83476", "type": "concept", "title": "Decision cadence, scenario planning, and executive tradeoff conversations"}], "description": "Students learn how attribution, experiments, and MMM inform different decisions."}]}, {"id": "13589355-fc76-411a-b0f8-bd81ed63f71f", "type": "topic", "title": "Pricing, Promotion, Revenue, and Demand Analytics", "description": "This unit connects marketing analytics to value capture through elasticity, willingness to pay, discounting, promotions, and revenue optimization.", "children": [{"id": "d58a85dd-b29f-44c9-a106-aa87cc885a6b", "type": "subtopic", "title": "Demand and elasticity", "children": [{"id": "f1b810c9-8cb6-4a9d-9cfa-3bb14cb18fa5", "type": "concept", "title": "Price elasticity, cross-elasticity, willingness to pay, and demand curves"}, {"id": "54fb6e5a-7634-4b10-80d1-8116d2cb1d19", "type": "concept", "title": "Survey, transaction, conjoint, test-market, and observational approaches"}, {"id": "397a7d80-6117-40fd-bd6a-12925a42f1bf", "type": "concept", "title": "Revenue, margin, volume, and profit tradeoffs"}], "description": "Students learn how price, value, competition, and demand interact."}, {"id": "9f1251b3-e336-4150-a831-f81f0b8f0702", "type": "subtopic", "title": "Promotion analytics", "children": [{"id": "c673e196-2018-4b75-8c79-d0b6ad66751c", "type": "concept", "title": "Discount depth, frequency, timing, cannibalization, pantry loading, and stockpiling"}, {"id": "1a8c127f-0a74-4d41-8360-2f17e8efb54c", "type": "concept", "title": "Promo lift, incremental margin, redemption, and customer quality"}, {"id": "41db4c64-6ba1-4f18-a00a-dec57d214f2a", "type": "concept", "title": "Coupon, loyalty, bundle, and channel promotion analysis"}], "description": "Promotions can create lift or simply shift timing. Students learn to measure both."}, {"id": "b49d0179-b7db-432a-b72f-594965fc31ba", "type": "subtopic", "title": "Revenue optimization", "children": [{"id": "074ba730-0ce2-48e9-9114-b62651a1164a", "type": "concept", "title": "Value-based pricing, bundles, tiers, freemium, subscriptions, and dynamic pricing"}, {"id": "91403cf0-27ef-4a82-b7d7-3c7c10da0061", "type": "concept", "title": "Price discrimination, product-line pricing, and revenue management"}, {"id": "e7b569cf-4f54-46cb-be2a-7df42c37a972", "type": "concept", "title": "Fairness, transparency, legal risk, and pricing ethics"}], "description": "Students connect marketing analytics to offer design and monetization."}]}, {"id": "0109bd21-3f5d-4d04-905b-aef9e7bbe2f7", "type": "topic", "title": "Brand, Campaign, Social Listening, and Market Response Analytics", "description": "Students analyze softer but measurable marketing assets: brand equity, awareness, sentiment, content performance, and competitive share of voice.", "children": [{"id": "31f28a7d-2c80-4632-ad29-038807b623ac", "type": "subtopic", "title": "Brand equity measurement", "children": [{"id": "13434483-82d7-4407-89c3-87d1844c49ba", "type": "concept", "title": "Awareness, consideration, preference, associations, salience, loyalty, and equity"}, {"id": "d9a8e4ae-e936-4321-8b87-a7115e14e76b", "type": "concept", "title": "Brand tracking surveys, panels, search interest, social signals, and sales response"}, {"id": "9f798604-55ba-432b-806b-0100cb6f8419", "type": "concept", "title": "Mental availability, physical availability, and brand health dashboards"}], "description": "Students learn that brand is measurable, but not reducible to one number."}, {"id": "761bd457-50b2-4a7b-81dc-aba85632a8a1", "type": "subtopic", "title": "Campaign measurement", "children": [{"id": "f952b527-ecdc-48ca-a468-5d603a54de2a", "type": "concept", "title": "Reach, frequency, GRPs, impressions, engagement, conversions, CPA, ROAS, and ROI"}, {"id": "b95255bd-7834-40a3-a90e-62346e73e256", "type": "concept", "title": "Creative testing, message experiments, and campaign diagnostics"}, {"id": "2a46f2a0-b5f4-4c26-ad9d-4694ee90b665", "type": "concept", "title": "Paid, owned, earned, shared media, and integrated reporting"}], "description": "Students design campaign measurement plans that link objectives, audiences, channels, creative, and outcomes."}, {"id": "730a57d7-88c8-40b4-8c58-4a8556003866", "type": "subtopic", "title": "Social listening and market intelligence", "children": [{"id": "ee280888-635e-4024-9b34-4b58c9a54dee", "type": "concept", "title": "Share of voice, sentiment, topics, communities, influence, and trend detection"}, {"id": "36db7724-fc63-451c-bc7b-60740246b414", "type": "concept", "title": "Competitive monitoring, launch tracking, reputation risk, and crisis signals"}, {"id": "c2e74924-d4ee-4b40-8e28-f9ab53ba189a", "type": "concept", "title": "Sampling bias, platform demographics, bots, sarcasm, and context loss"}], "description": "Students evaluate the opportunities and pitfalls of social and market-response data."}]}, {"id": "68192a91-95c6-4b2c-8c72-03cd66b58b44", "type": "topic", "title": "Privacy, Consent, Bias, Governance, and Responsible Targeting", "description": "This section treats responsible analytics as a core capability, not a compliance footnote. Students learn to evaluate privacy risk, fairness, consent, and algorithmic harm.", "children": [{"id": "b2ae4cf9-d291-4080-b135-816eb0e2abb9", "type": "subtopic", "title": "Privacy and consent", "children": [{"id": "7828eb33-efa5-419f-84eb-4bfa53927e54", "type": "concept", "title": "Consent, purpose limitation, data minimization, retention, and user rights"}, {"id": "60b67d35-116c-42ea-94dc-7fce1543da71", "type": "concept", "title": "Cookies, mobile identifiers, clean rooms, consent mode, and server-side tracking"}, {"id": "9f872919-de05-4361-9916-9c7be6d436eb", "type": "concept", "title": "FTC guidance, platform policies, and global regulatory awareness"}], "description": "Students learn how modern marketing measurement operates under privacy, consent, and tracking constraints."}, {"id": "a80d34cc-7c8c-49d3-b6c9-de96bcd787d7", "type": "subtopic", "title": "Bias and fairness", "children": [{"id": "f081ace2-aa0a-44f6-a35a-dd61ac360a5c", "type": "concept", "title": "Proxy variables, disparate impact, sensitive attributes, and exclusion"}, {"id": "2e266f73-4100-412e-900c-75b5b0dd7a9a", "type": "concept", "title": "Audience targeting, lookalikes, personalization, and credit/health/housing-adjacent risk"}, {"id": "f66c049d-1513-4ecc-904f-3070e2367b52", "type": "concept", "title": "Fairness metrics, bias checks, and human review"}], "description": "Marketing algorithms can reproduce exclusion or harm. Students learn to audit models and targeting choices."}, {"id": "ebfa8051-be65-4063-ba3f-4ae15b19d6e4", "type": "subtopic", "title": "Governance and responsible activation", "children": [{"id": "eab6a02a-055a-4f35-b5f5-5d3294ffb6d2", "type": "concept", "title": "Data access, role permissions, documentation, approval workflows, and model cards"}, {"id": "0553990a-6eb4-4897-8d10-f51ac0ad7782", "type": "concept", "title": "Experiment ethics, customer dignity, dark patterns, and persuasive design limits"}, {"id": "fc5c890b-ac48-46a2-a957-4939b246fcbf", "type": "concept", "title": "Responsible targeting checklist and escalation paths"}], "description": "Responsible analytics requires process, not just good intentions."}]}, {"id": "40538d4e-b6c6-4dca-967b-b0ef066a7b1e", "type": "topic", "title": "Capstone: Analytics Strategy, Executive Recommendation, and Portfolio", "description": "The course culminates in a real-world analytics project where students connect data, model, decision, ethics, and executive communication.", "children": [{"id": "fc9f7908-00c6-4b24-b355-46ef16d742cc", "type": "subtopic", "title": "Project scoping and data plan", "children": [{"id": "dc57b135-a664-4dd4-96d0-7a9aa298a7ce", "type": "concept", "title": "Business question, stakeholder, action, metric, data sources, and risks"}, {"id": "e1d3f00a-ab4e-4b6b-a8bf-13b3ead282ab", "type": "concept", "title": "Data dictionary, joins, cleaning plan, assumptions, and limitations"}, {"id": "53cdb08f-227d-4922-9bb6-b62641535ba1", "type": "concept", "title": "Ethics, privacy, and governance review before analysis"}], "description": "Students define a project that connects a real marketing decision to credible data and feasible analysis."}, {"id": "65380831-1b2a-482c-9517-d07057c9801e", "type": "subtopic", "title": "Analysis, modeling, and recommendation", "children": [{"id": "36c57fdf-1fab-4449-9aa2-e0dfb2573f1d", "type": "concept", "title": "Exploratory analysis, model choice, validation, interpretation, and sensitivity checks"}, {"id": "ee681169-640c-4e9a-bfa6-5e0a69be176c", "type": "concept", "title": "Tradeoffs, uncertainty, alternatives, and implementation constraints"}, {"id": "e02f203c-8788-4066-9662-3ca713b821c9", "type": "concept", "title": "Clear recommendation tied to revenue, margin, customer value, or brand outcome"}], "description": "The capstone requires students to move from analysis to a decision-ready recommendation."}, {"id": "9fc33f93-5acd-4710-bd53-8341139f95ab", "type": "subtopic", "title": "Executive presentation and portfolio artifact", "children": [{"id": "dd7e4e43-5df2-4b67-8086-22c48b57cb87", "type": "concept", "title": "One-page executive memo, dashboard, appendix, and reproducible workbook/notebook"}, {"id": "62a835c2-66e0-407f-829e-9cf919da6446", "type": "concept", "title": "Presentation structure, stakeholder Q&A, and visual clarity"}, {"id": "50daee10-dcf5-4075-a85b-7197c69e2952", "type": "concept", "title": "Portfolio reflection on decision impact, ethics, and next steps"}], "description": "Students practice communicating analytics like a marketing leader, not only a technician."}]}], "dbBacked": true}$mkanjson$::jsonb,
