insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('9eeff532-6580-46fa-b50b-b5da6ec01a28', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Marketing Analytics as Decision Science', 'Students begin by learning that analytics is not report-making; it is disciplined decision support. The unit links business questions, customer strategy, measurement design, and managerial action.', 0),
  ('a8d20804-8e6d-44d0-9633-63bac9d42150', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '9eeff532-6580-46fa-b50b-b5da6ec01a28', 'subtopic'::public.curated_course_node_type, 'Business questions before methods', 'Students learn to start with a decision, not a dataset. Good marketing analytics clarifies what action will change if the analysis is right.', 0),
  ('6c991122-972e-4163-a2fb-f1dcc06a5469', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'a8d20804-8e6d-44d0-9633-63bac9d42150', 'concept'::public.curated_course_node_type, 'Decision owner, business question, action threshold, and time horizon', null, 0),
  ('e351bb14-4f03-4e20-b1bd-868ffd5f73e3', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'a8d20804-8e6d-44d0-9633-63bac9d42150', 'concept'::public.curated_course_node_type, 'Descriptive, diagnostic, predictive, prescriptive, and causal questions', null, 1),
  ('5a4f0a1d-b98c-455e-b803-b86b938a5689', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'a8d20804-8e6d-44d0-9633-63bac9d42150', 'concept'::public.curated_course_node_type, 'Translating vague goals into testable analytic problems', null, 2),
  ('4b8f9785-a4b1-42be-b0f8-ae6278a2336b', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '9eeff532-6580-46fa-b50b-b5da6ec01a28', 'subtopic'::public.curated_course_node_type, 'Marketing strategy and analytics fit', 'Analytics becomes useful when it supports segmentation, targeting, positioning, product, price, promotion, channel, and retention decisions.', 1),
  ('0ec64b51-da7f-44c2-9513-b032b5994b69', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '4b8f9785-a4b1-42be-b0f8-ae6278a2336b', 'concept'::public.curated_course_node_type, 'STP, marketing mix, funnel, and customer equity logic', null, 0),
  ('94e31196-aae7-470f-a00c-960124fbba09', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '4b8f9785-a4b1-42be-b0f8-ae6278a2336b', 'concept'::public.curated_course_node_type, 'Acquisition, conversion, retention, monetization, loyalty, and advocacy', null, 1),
  ('dde8d92a-1831-4e2b-ae5c-e7e50d218f03', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '4b8f9785-a4b1-42be-b0f8-ae6278a2336b', 'concept'::public.curated_course_node_type, 'How analytics connects to budgeting, ROI, and resource allocation', null, 2),
  ('cfac81a7-aa0f-4ce7-8f49-b6eca57fa326', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '9eeff532-6580-46fa-b50b-b5da6ec01a28', 'subtopic'::public.curated_course_node_type, 'Analytic workflow and reproducibility', 'Students learn the workflow from problem framing through data, model, interpretation, recommendation, and monitoring.', 2),
  ('1a1a40eb-82e7-40b2-9e0d-20d5f9db045c', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'cfac81a7-aa0f-4ce7-8f49-b6eca57fa326', 'concept'::public.curated_course_node_type, 'Scoping, data audit, cleaning, exploration, modeling, validation, and reporting', null, 0),
  ('29a57ac5-e743-4267-99f2-9cc05c7e9aad', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'cfac81a7-aa0f-4ce7-8f49-b6eca57fa326', 'concept'::public.curated_course_node_type, 'Assumptions, versioning, reproducible files, and documentation', null, 1),
  ('924eefc6-8409-4696-b1f2-1cf5b9cc1300', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'cfac81a7-aa0f-4ce7-8f49-b6eca57fa326', 'concept'::public.curated_course_node_type, 'Decision-ready recommendations and post-decision learning loops', null, 2),
  ('8511ed97-41b8-4bcc-aace-2a90e4446344', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Marketing Data Sources, Martech, SQL, and Data Quality', 'This section teaches students where marketing data comes from, how it is joined, and why data quality determines whether analysis can be trusted.', 1),
  ('35d2124a-7c75-4a73-b93f-256bf58cd19b', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '8511ed97-41b8-4bcc-aace-2a90e4446344', 'subtopic'::public.curated_course_node_type, 'Data ecosystem and martech', 'Marketing data comes from many tools that rarely agree perfectly. Students learn the ecosystem before analyzing it.', 0),
  ('8b25d8e0-b01e-4295-8283-23dd39bd197c', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '35d2124a-7c75-4a73-b93f-256bf58cd19b', 'concept'::public.curated_course_node_type, 'CRM, CDP, web analytics, ad platforms, email, ecommerce, surveys, POS, and loyalty data', null, 0),
  ('1859a231-fa2a-4b96-b58a-452d510718c5', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '35d2124a-7c75-4a73-b93f-256bf58cd19b', 'concept'::public.curated_course_node_type, 'First-party, second-party, third-party, syndicated, and public data', null, 1),
  ('d21cdb23-3a8a-47eb-a0a2-da2b8d69ec78', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '35d2124a-7c75-4a73-b93f-256bf58cd19b', 'concept'::public.curated_course_node_type, 'Identity resolution, event tracking, tags, UTMs, pixels, and APIs', null, 2),
  ('0052b48f-cf55-43e8-a0ee-dd03c8ceac40', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '8511ed97-41b8-4bcc-aace-2a90e4446344', 'subtopic'::public.curated_course_node_type, 'SQL and data preparation', 'Students practice the extraction and joining skills needed to turn raw records into analyzable marketing tables.', 1),
  ('ea0b8197-506d-46a1-9983-1dc994eaf81d', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '0052b48f-cf55-43e8-a0ee-dd03c8ceac40', 'concept'::public.curated_course_node_type, 'SELECT, WHERE, JOIN, GROUP BY, CASE, window functions, and date logic', null, 0),
  ('bde4b119-cc5b-465a-8e52-447dd3a3456d', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '0052b48f-cf55-43e8-a0ee-dd03c8ceac40', 'concept'::public.curated_course_node_type, 'Customer, transaction, event, campaign, product, and touchpoint tables', null, 1),
  ('77bbc757-06ae-4a88-8566-5204cb91ade7', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '0052b48f-cf55-43e8-a0ee-dd03c8ceac40', 'concept'::public.curated_course_node_type, 'Feature engineering for recency, frequency, monetary value, source, and engagement', null, 2),
  ('de31c3fa-9003-4669-9df3-c2f132b96273', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '8511ed97-41b8-4bcc-aace-2a90e4446344', 'subtopic'::public.curated_course_node_type, 'Data quality and governance', 'Students learn why missingness, duplication, tracking drift, and inconsistent definitions can destroy analytic credibility.', 2),
  ('03fe35a4-592e-4fdc-8ba3-f2c9913f0138', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'de31c3fa-9003-4669-9df3-c2f132b96273', 'concept'::public.curated_course_node_type, 'Data dictionaries, metric definitions, lineage, and ownership', null, 0),
  ('a6bb8dd8-49b8-444e-a52e-993f3d357ff0', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'de31c3fa-9003-4669-9df3-c2f132b96273', 'concept'::public.curated_course_node_type, 'Missing data, outliers, bot traffic, duplicate customers, and attribution gaps', null, 1),
  ('9721f823-5bf5-44a3-8eb3-efc154ff2a10', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'de31c3fa-9003-4669-9df3-c2f132b96273', 'concept'::public.curated_course_node_type, 'Quality checks, reconciliation, access control, and audit trails', null, 2),
  ('be35d93c-cdbb-4d35-9a65-78c8fb241710', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Metrics, KPIs, Dashboards, and Insight Communication', 'Students learn to design metrics that match strategy, avoid vanity measures, and communicate insights in dashboards that drive decisions.', 2),
  ('5c999598-65ca-472c-aed0-572b9bbcf349', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'be35d93c-cdbb-4d35-9a65-78c8fb241710', 'subtopic'::public.curated_course_node_type, 'Metric architecture', 'Students learn to distinguish strategic KPIs from diagnostic metrics and vanity measures.', 0),
  ('559d15d0-102a-4169-82a3-4a0b40eab7c5', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '5c999598-65ca-472c-aed0-572b9bbcf349', 'concept'::public.curated_course_node_type, 'North-star metric, input metrics, output metrics, guardrails, and leading indicators', null, 0),
  ('46b9b98a-0fe9-4a65-9620-7f39bc48ec7a', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '5c999598-65ca-472c-aed0-572b9bbcf349', 'concept'::public.curated_course_node_type, 'Awareness, reach, engagement, conversion, retention, revenue, profit, and loyalty metrics', null, 1),
  ('5561fdf1-a082-4ca0-9fd9-902bc5c0c411', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '5c999598-65ca-472c-aed0-572b9bbcf349', 'concept'::public.curated_course_node_type, 'Metric trees that connect marketing activity to business outcomes', null, 2),
  ('fdaff5c6-dcbd-4c00-ae56-526de8430e4f', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'be35d93c-cdbb-4d35-9a65-78c8fb241710', 'subtopic'::public.curated_course_node_type, 'Dashboard design', 'A dashboard should answer recurring questions quickly. Students design dashboards around users, decisions, and exceptions.', 1),
  ('8349cd44-ae8f-4d32-8b73-764a82a43763', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'fdaff5c6-dcbd-4c00-ae56-526de8430e4f', 'concept'::public.curated_course_node_type, 'Executive, manager, channel, campaign, and analyst dashboard roles', null, 0),
  ('e4d110fa-c938-473b-a951-fb8e972141ac', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'fdaff5c6-dcbd-4c00-ae56-526de8430e4f', 'concept'::public.curated_course_node_type, 'Visualization choices, filters, annotations, benchmarks, and targets', null, 1),
  ('a51169c7-07b0-488e-892c-b3cd5a1ea5c2', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'fdaff5c6-dcbd-4c00-ae56-526de8430e4f', 'concept'::public.curated_course_node_type, 'Avoiding clutter, misleading scales, and disconnected chart collections', null, 2),
  ('2c40f8c3-84ad-48b1-a250-3c7f1dcb4cae', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'be35d93c-cdbb-4d35-9a65-78c8fb241710', 'subtopic'::public.curated_course_node_type, 'Insight storytelling', 'Students learn to communicate analysis as a recommendation, not a pile of charts.', 2),
  ('3e1c55b1-2708-43c2-bd73-59d117567210', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '2c40f8c3-84ad-48b1-a250-3c7f1dcb4cae', 'concept'::public.curated_course_node_type, 'Situation, complication, insight, implication, and action', null, 0),
  ('6a01eda3-7747-4037-9d9a-d69e41b8d03b', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '2c40f8c3-84ad-48b1-a250-3c7f1dcb4cae', 'concept'::public.curated_course_node_type, 'Executive summaries, decision memos, and meeting narratives', null, 1),
  ('5108935f-03fb-4f42-90b0-78aa71d8f38d', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '2c40f8c3-84ad-48b1-a250-3c7f1dcb4cae', 'concept'::public.curated_course_node_type, 'Uncertainty, caveats, confidence, and next-best analysis', null, 2),
  ('ffaafc4b-10d7-46e3-9f5c-c09aff3e0407', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Consumer Behavior, Customer Journeys, and CRM Analytics', 'This topic connects behavioral theory with observed customer data so students can interpret journeys, funnels, engagement, and relationship signals.', 3);
