values
  ('d8b34e69-529f-4ad5-b547-061db8c50fcd', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'ffaafc4b-10d7-46e3-9f5c-c09aff3e0407', 'subtopic'::public.curated_course_node_type, 'Behavioral foundations', 'Students connect observable behavior to attention, motivation, perception, memory, attitudes, persuasion, and social influence.', 0),
  ('db6ac7d8-6cf2-401a-a21e-0dabe711a889', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'd8b34e69-529f-4ad5-b547-061db8c50fcd', 'concept'::public.curated_course_node_type, 'Decision process, involvement, heuristics, and behavioral bias', null, 0),
