  ('6cea6fd4-5236-4ad1-b0b3-a91504d57401', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'd664cdd1-88ad-4b3e-b173-320c18f829d0', 'concept'::public.curated_course_node_type, 'Funnels, paths, drop-off, time lag, micro-conversions, and cohorts', null, 0),
  ('36b6a4c3-36bc-425a-93a0-4ffc1bf52703', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'd664cdd1-88ad-4b3e-b173-320c18f829d0', 'concept'::public.curated_course_node_type, 'Journey stages, pain points, content needs, and touchpoint roles', null, 1),
  ('03f3fbc8-3163-44cb-81fc-bda8c10723de', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'd664cdd1-88ad-4b3e-b173-320c18f829d0', 'concept'::public.curated_course_node_type, 'Omnichannel journeys and cross-device measurement limits', null, 2),
