  ('1307543d-36c6-4416-8ba6-280b31a4eb3a', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'b3cc5932-d248-4a4a-9de7-b8a226330ac3', 'concept'::public.curated_course_node_type, 'Lead scoring, account history, service interactions, offers, and lifecycle stages', null, 0),
  ('ec54eadc-8d55-4526-b5b4-4b3f74292410', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'b3cc5932-d248-4a4a-9de7-b8a226330ac3', 'concept'::public.curated_course_node_type, 'RFM, engagement scoring, next-best action, and customer health', null, 1),
  ('21b9b80c-7b59-4eca-a94b-137d8d308004', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'b3cc5932-d248-4a4a-9de7-b8a226330ac3', 'concept'::public.curated_course_node_type, 'Sales and marketing alignment through shared customer data', null, 2),
  ('8fd251c7-e052-49bb-8caa-93049d7a258b', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Segmentation, Targeting, Clustering, and Personalization', 'Students study how to group customers meaningfully and turn segments into targeting, personalization, and positioning decisions.', 4),
