  ('11ea1989-fa8d-4843-8ab2-90c4ddc54bfb', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f8ca82e0-bdc2-4482-b63d-9aac93997bbb', 'concept'::public.curated_course_node_type, 'Needs-based, behavioral, demographic, attitudinal, value-based, and occasion-based segments', null, 0),
  ('c34dec67-1363-4118-9657-6591838a20b6', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f8ca82e0-bdc2-4482-b63d-9aac93997bbb', 'concept'::public.curated_course_node_type, 'Segment size, growth, profitability, reachability, stability, and distinctiveness', null, 1),
  ('ecd46029-5c00-4a08-bc2c-1472defd9f30', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f8ca82e0-bdc2-4482-b63d-9aac93997bbb', 'concept'::public.curated_course_node_type, 'Targeting choices, positioning implications, and offer design', null, 2),
  ('f531fa05-139a-4ba2-8847-7b4cdd84d953', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '8fd251c7-e052-49bb-8caa-93049d7a258b', 'subtopic'::public.curated_course_node_type, 'Clustering and profiling', 'Students learn how clustering algorithms create groups and why interpretation matters as much as computation.', 1),
