  ('d3b7cdff-6e8b-4c65-be2a-1c9e72502773', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f531fa05-139a-4ba2-8847-7b4cdd84d953', 'concept'::public.curated_course_node_type, 'Feature scaling, number of clusters, validation, and cluster stability', null, 1),
  ('dd75fe28-c037-494b-9f1f-8b03903f0b62', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f531fa05-139a-4ba2-8847-7b4cdd84d953', 'concept'::public.curated_course_node_type, 'Personas, segment profiles, naming, and managerial translation', null, 2),
  ('3e2d6de0-7a73-41a6-95b9-1021a6759aaf', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '8fd251c7-e052-49bb-8caa-93049d7a258b', 'subtopic'::public.curated_course_node_type, 'Personalization and recommendation', 'Students evaluate personalization as a tradeoff among relevance, efficiency, privacy, fairness, and customer experience.', 2),
  ('889c0c5d-60d6-44e0-b47e-fcc42f65105b', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '3e2d6de0-7a73-41a6-95b9-1021a6759aaf', 'concept'::public.curated_course_node_type, 'Rules-based personalization, propensity scores, recommendations, and dynamic content', null, 0),
  ('31d5ed77-f1f7-436a-a215-0227a38c88b5', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '3e2d6de0-7a73-41a6-95b9-1021a6759aaf', 'concept'::public.curated_course_node_type, 'Cold start, overfitting, frequency, fatigue, and customer creepiness', null, 1),
  ('28d5c950-609c-4107-865b-349defe5c6ba', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '3e2d6de0-7a73-41a6-95b9-1021a6759aaf', 'concept'::public.curated_course_node_type, 'Testing personalized treatments against generic alternatives', null, 2),
  ('72614548-47ca-42e7-a1b4-720e7068c0b1', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Customer Lifetime Value, Retention, Churn, and Customer Equity', 'This unit develops the financial logic of customer relationships: acquisition cost, retention, churn, margin, discounting, and long-run value.', 5),
  ('f467c77b-88be-4e99-9a00-7495e401187c', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '72614548-47ca-42e7-a1b4-720e7068c0b1', 'subtopic'::public.curated_course_node_type, 'CLV foundations', 'Students learn CLV as the financial bridge between marketing actions and firm value.', 0),
  ('ef821ca3-c58b-4ef4-9216-a2685037a04f', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f467c77b-88be-4e99-9a00-7495e401187c', 'concept'::public.curated_course_node_type, 'Margin, retention, discount rate, purchase frequency, acquisition cost, and payback', null, 0),
  ('998c17ff-498f-46b8-bd32-abbccc5cadc0', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f467c77b-88be-4e99-9a00-7495e401187c', 'concept'::public.curated_course_node_type, 'Historic, predictive, cohort, and probabilistic CLV', null, 1),
  ('42e31533-16a4-4e6c-9314-04b001c98976', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f467c77b-88be-4e99-9a00-7495e401187c', 'concept'::public.curated_course_node_type, 'Customer equity, portfolio value, and segment profitability', null, 2),
  ('97b4e675-8347-4b29-80ae-e344b04db846', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '72614548-47ca-42e7-a1b4-720e7068c0b1', 'subtopic'::public.curated_course_node_type, 'Churn and retention analytics', 'Retention is often more valuable than acquisition. Students learn to predict and diagnose churn while respecting causal limits.', 1),
  ('4229b545-982f-440c-9425-a2d0b31f1ac5', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '97b4e675-8347-4b29-80ae-e344b04db846', 'concept'::public.curated_course_node_type, 'Voluntary churn, involuntary churn, inactivity, downgrades, and dormancy', null, 0),
  ('b92c2ba1-ca1a-4770-a7ce-50a4d262ca97', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '97b4e675-8347-4b29-80ae-e344b04db846', 'concept'::public.curated_course_node_type, 'Churn labels, observation windows, leakage, and class imbalance', null, 1),
  ('8107126e-75a4-4a02-834c-9d5a1cd278c7', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '97b4e675-8347-4b29-80ae-e344b04db846', 'concept'::public.curated_course_node_type, 'Retention offers, win-back, loyalty programs, and intervention timing', null, 2),
  ('a5786631-ee33-441a-ac9c-23ec53c6d965', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '72614548-47ca-42e7-a1b4-720e7068c0b1', 'subtopic'::public.curated_course_node_type, 'Customer acquisition economics', 'Students connect CLV to CAC, media spend, channels, and growth quality.', 2),
  ('3a4fa6ad-eb4b-4307-936f-ce18a0c9de16', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'a5786631-ee33-441a-ac9c-23ec53c6d965', 'concept'::public.curated_course_node_type, 'CAC, LTV:CAC, payback period, contribution margin, and unit economics', null, 0),
  ('d5a1fb7f-acef-4930-8efe-4b4810f3e480', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'a5786631-ee33-441a-ac9c-23ec53c6d965', 'concept'::public.curated_course_node_type, 'Acquisition source quality, cohort retention, and channel profitability', null, 1),
  ('f5fb0b7c-231d-49e0-8220-883ff16a7833', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'a5786631-ee33-441a-ac9c-23ec53c6d965', 'concept'::public.curated_course_node_type, 'Growth tradeoffs between scale, efficiency, and customer quality', null, 2),
  ('ba1b02c7-c5b0-4004-9d45-f335a6cfac8f', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Marketing Research, Surveys, Sampling, and Measurement Validity', 'Students learn how survey and research design shape the quality of analytic conclusions before any model is built.', 6),
  ('a8d5f12f-a0df-4c68-bd23-cdfb9a10a93e', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'ba1b02c7-c5b0-4004-9d45-f335a6cfac8f', 'subtopic'::public.curated_course_node_type, 'Research design', 'Students learn to choose qualitative, quantitative, experimental, or mixed methods based on the decision problem.', 0);
