  ('c615622e-14b4-4e5b-a6eb-9f47949bb195', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'a8d5f12f-a0df-4c68-bd23-cdfb9a10a93e', 'concept'::public.curated_course_node_type, 'Problem definition, hypotheses, research objectives, and decision criteria', null, 0),
