  ('53577488-6ced-4a45-ba0e-b0c6f84cdef1', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '0ece43c8-419f-4098-8394-0f18533bd08b', 'concept'::public.curated_course_node_type, 'Sampling frame, probability, nonprobability, bias, weighting, and response rate', null, 0),
