  ('1afc9a08-6d28-411a-9e9b-b975229a9d41', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'd11d2d4a-e3ef-401e-b049-8b4b56efff81', 'concept'::public.curated_course_node_type, 'Consent, privacy, deception, incentives, and vulnerable populations', null, 0),
  ('44483178-ec54-456a-abe9-20e7cd26ece9', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'd11d2d4a-e3ef-401e-b049-8b4b56efff81', 'concept'::public.curated_course_node_type, 'Transparency about uncertainty, assumptions, and representativeness', null, 1),
  ('0c91c9a4-571f-4cf7-a110-2d29c0e5add0', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'd11d2d4a-e3ef-401e-b049-8b4b56efff81', 'concept'::public.curated_course_node_type, 'Turning research findings into actionable insight without overclaiming', null, 2),
  ('a728d1a2-13fa-43b2-a8a5-648a5eeaaa7e', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Predictive Modeling: Regression, Classification, and Forecasting', 'This section gives students applied modeling tools for predicting response, sales, churn, demand, and campaign outcomes.', 7),
