  ('a63987db-926b-40f3-869c-52ea8c48f260', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '10c01c9a-6312-4006-9a6d-689522e3268a', 'concept'::public.curated_course_node_type, 'Linear and logistic regression, interactions, nonlinearities, and transformations', null, 0),
  ('68d64287-8597-4497-9889-5d87163d93ba', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '10c01c9a-6312-4006-9a6d-689522e3268a', 'concept'::public.curated_course_node_type, 'Response, conversion, sales, spend, price, and demand models', null, 1),
  ('9052a507-0601-46fb-aec1-dc8ac80f6cd3', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '10c01c9a-6312-4006-9a6d-689522e3268a', 'concept'::public.curated_course_node_type, 'Coefficients, confidence, fit, residuals, and business interpretation', null, 2),
  ('f97e0d1a-b89a-4db8-be29-7e4153292252', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'a728d1a2-13fa-43b2-a8a5-648a5eeaaa7e', 'subtopic'::public.curated_course_node_type, 'Classification and model evaluation', 'Predictive marketing models require careful evaluation against business costs and benefits.', 1),
  ('20148cc0-e119-4dfc-86f9-290b813189d1', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f97e0d1a-b89a-4db8-be29-7e4153292252', 'concept'::public.curated_course_node_type, 'Propensity modeling, churn prediction, lead scoring, and next-best offer', null, 0),
  ('1d8269b8-e947-4da4-bb9a-2cd5b98755ac', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f97e0d1a-b89a-4db8-be29-7e4153292252', 'concept'::public.curated_course_node_type, 'Train/test splits, cross-validation, ROC/AUC, precision, recall, lift, and calibration', null, 1),
  ('416cb4ec-a661-4a45-b1a2-4f0c24694ad7', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'f97e0d1a-b89a-4db8-be29-7e4153292252', 'concept'::public.curated_course_node_type, 'Threshold selection, profit curves, and intervention economics', null, 2),
