  ('1d9ef6a4-a2cf-416a-bdb3-850f66cf50c7', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '9a922ad0-8e75-4f9b-ae9c-ba35ef5c1943', 'concept'::public.curated_course_node_type, 'Holdout validation, forecast error, scenario ranges, and confidence intervals', null, 1),
