  ('dc763243-6e24-416c-b8d1-cdc7b81d3ce2', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'e2e64f03-2c86-4232-b8e4-50941e868e1e', 'concept'::public.curated_course_node_type, 'Incremental revenue, conversion lift, brand lift, and sales lift', null, 0),
  ('60c148a4-9e0f-4ea8-abc1-9deaf5f534c4', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'e2e64f03-2c86-4232-b8e4-50941e868e1e', 'concept'::public.curated_course_node_type, 'Selection bias, targeting bias, seasonality, and regression to the mean', null, 1),
  ('72b3429b-71dc-4fea-9e4d-c2dbca2557b6', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'e2e64f03-2c86-4232-b8e4-50941e868e1e', 'concept'::public.curated_course_node_type, 'Platform lift studies, ghost ads, conversion lift, and holdout groups', null, 2),
