  ('8161b1a6-38ff-4f9e-b006-1b7814ff6234', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', 'e3fd2aaa-7c29-42ee-82b4-31bc19933f18', 'concept'::public.curated_course_node_type, 'Confounding, omitted variables, parallel trends, and robustness checks', null, 1),
