  ('4c10fdb7-e21b-4d59-84db-361214711c5d', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', null, 'topic'::public.curated_course_node_type, 'Digital Analytics: Web, App, Search, Social, Email, and Content', 'This topic teaches the measurement logic of modern digital channels, from search intent to content engagement and conversion paths.', 9),
