  ('17a703d8-d63c-4791-a421-3cc929dea54d', 'e6f7a8b9-0c1d-4e76-9f37-4a5b6c7d8e96', '20e5153d-c4d0-44de-9302-59018e2cf7ab', 'concept'::public.curated_course_node_type, 'Channel allocation, marginal ROI, diminishing returns, and response curves', null, 0),
